/**
 * Generates the iOS app icon for BeenBy from a single source image.
 *
 * Usage:
 *   node scripts/generate-ios-icon.mjs [path-to-source.png]
 *
 * Default source: assets/app-icon.png
 *
 * Capacitor's AppIcon.appiconset uses a single universal 1024x1024 icon
 * (AppIcon-512@2x.png); Xcode renders all other sizes from it. The script:
 *   1. Flattens transparency onto white (App Store rejects icons with alpha).
 *   2. Resizes/crops to a full-bleed 1024x1024 square.
 *   3. Writes ios/App/App/Assets.xcassets/AppIcon.appiconset/.
 *
 * The iOS project is generated by `npx cap add ios` and is not in git, so the
 * script creates the folder if needed and can be re-run after every sync.
 * Requires ImageMagick (`magick`) on PATH.
 */
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const source = process.argv[2] ?? "assets/app-icon.png";
const OUT_DIR = "ios/App/App/Assets.xcassets/AppIcon.appiconset";
const OUT_FILE = "AppIcon-512@2x.png";

if (!existsSync(source)) {
  console.error(`Hittar inte källbilden ${source}.`);
  console.error("Lägg en kvadratisk bild där eller ange sökväg:");
  console.error("  node scripts/generate-ios-icon.mjs /sökväg/till/ikon.png");
  process.exit(1);
}

mkdirSync(OUT_DIR, { recursive: true });

execFileSync("magick", [
  source,
  "-resize",
  "1024x1024^", // fyll hela ytan, beskär överskott
  "-gravity",
  "center",
  "-extent",
  "1024x1024",
  "-background",
  "white",
  "-alpha",
  "remove", // ingen alfa — App Store-krav
  "-strip",
  join(OUT_DIR, OUT_FILE),
]);

writeFileSync(
  join(OUT_DIR, "Contents.json"),
  JSON.stringify(
    {
      images: [
        {
          size: "1024x1024",
          idiom: "universal",
          filename: OUT_FILE,
          scale: "1x",
        },
      ],
      info: { version: 1, author: "xcode" },
    },
    null,
    2,
  ) + "\n",
);

console.log(`Appikon genererad: ${OUT_DIR}/${OUT_FILE} (1024x1024, utan alfa)`);
console.log("Öppna Xcode och bygg om — ikonen plockas upp automatiskt.");
